import hashlib,json,os,sys,torch
p=sys.argv[1];fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW);h=hashlib.sha256();z=0
while True:
 b=os.read(fd,8388608)
 if not b:break
 h.update(b);z+=len(b)
os.close(fd);v=torch.load(p,map_location='cpu',weights_only=True);s=[v];n=0
while s:
 x=s.pop()
 if isinstance(x,dict):s.extend(x.values())
 elif isinstance(x,(list,tuple)):s.extend(x)
 elif isinstance(x,torch.Tensor):
  n+=1
  assert not (x.is_floating_point() or x.is_complex()) or torch.isfinite(x).all().item()
print(json.dumps({'checkpoint_bytes':z,'checkpoint_sha256':h.hexdigest(),'finite':True,'map_location':'cpu','tensor_count':n,'weights_only':True},sort_keys=True))
